SELECT c.id AS contact_id, c.first_name, c.last_name, c.email, c.owner_id, u.name AS owner_name, (SELECT timezone FROM company_profile WHERE id = 1) AS timezone
FROM contacts c LEFT JOIN users u ON u.id = c.owner_id
WHERE c.booking_token = $1 AND c.is_archived = false;

SELECT due_at, COALESCE(end_at, due_at) AS end_at FROM activities
WHERE user_id = $1 AND due_at IS NOT NULL AND COALESCE(is_completed, false) = false
  AND due_at >= now() AND due_at <= now() + interval '14 days';

