// Working-hours model: Mon-Fri, 9am-5pm, 60-min slots, in the owner's
// timezone (falls back to America/New_York if they haven't set one in
// Settings). 14-day window, 2-hour minimum lead time from now. Busy time
// is any activity with a due_at set (matches Check Event Conflict's
// definition elsewhere in this app) — not just type='meeting', since an
// existing Inspection/Call/Site Visit on the calendar should block the
// slot too.
const contact = $('Look Up Contact By Token: Availability').item.json;
const tz = contact.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);
const leadTime = now.plus({ hours: 2 });
const windowEnd = now.plus({ days: 14 });

const busy = $input.all().map((i) => ({
  start: DateTime.fromISO(i.json.due_at, { zone: 'utc' }),
  end: DateTime.fromISO(i.json.end_at, { zone: 'utc' }),
}));

function overlaps(slotStart, slotEnd) {
  return busy.some((b) => slotStart < b.end && slotEnd > b.start);
}

const byDay = {};
for (let d = 0; d <= 14; d++) {
  const day = now.plus({ days: d }).startOf('day');
  if (day > windowEnd) break;
  if (day.weekday === 6 || day.weekday === 7) continue; // Sat/Sun
  for (let h = 9; h < 17; h++) {
    const slotStart = day.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
    const slotEnd = slotStart.plus({ minutes: 60 });
    if (slotStart < leadTime) continue;
    if (overlaps(slotStart.toUTC(), slotEnd.toUTC())) continue;
    const dayKey = slotStart.toISODate();
    (byDay[dayKey] ||= []).push({
      start_at: slotStart.toUTC().toISO(),
      label: slotStart.toFormat('h:mm a'),
    });
  }
}

const days = Object.keys(byDay).sort().map((date) => ({
  date,
  label: DateTime.fromISO(date, { zone: tz }).toFormat('EEEE, MMM d'),
  slots: byDay[date],
}));

return [{
  json: {
    contact_first_name: contact.first_name,
    contact_last_name: contact.last_name,
    owner_name: contact.owner_name,
    timezone: tz,
    days,
  },
}];

const body = $('Webhook: book-inspection-public').first().json.body || {};
const token = (body.token || '').toString().trim();
const startAt = (body.start_at || '').toString().trim();
if (!token || !startAt) throw new Error('token and start_at are required.');
const parsed = DateTime.fromISO(startAt);
if (!parsed.isValid) throw new Error('"start_at" must be a valid date/time.');
if (parsed < DateTime.now()) throw new Error('"start_at" must be in the future.');
return [{ json: { token, startAt } }];

