    timezone: contact.timezone,
    unsubscribe_token: contact.unsubscribe_token,
    startAt,
    deal_id: dealId,
    activity_id: activityId,
  },
}];

// Working-hours model: Mon-Fri, 9am-5pm, 60-min slots, in the CRM's
// system timezone (Settings -> Timezone). 14-day window, 2-hour minimum
// lead time from now. Company-wide availability — a slot is blocked if
// ANY active field rep has a due_at'd activity overlapping it. No
// per-rep round robin here: this form doesn't pin the visitor to one
// rep, so it just shows real open time across the whole team.
const tzRow = $('Get Company Timezone: Generic').item.json;
const tz = tzRow.timezone || 'America/New_York';
const now = DateTime.now().setZone(tz);
const leadTime = now.plus({ hours: 2 });
const windowEnd = now.plus({ days: 14 });

const busy = $input.all().map((i) => ({
  start: DateTime.fromISO(i.json.due_at, { zone: 'utc' }),
  end: DateTime.fromISO(i.json.end_at, { zone: 'utc' }),
}));

function overlaps(slotStart, slotEnd) {
  return busy.some((b) => slotStart < b.end && slotEnd > b.start);
}

const byDay = {};
for (let d = 0; d <= 14; d++) {
  const day = now.plus({ days: d }).startOf('day');
  if (day > windowEnd) break;
  if (day.weekday === 6 || day.weekday === 7) continue; // Sat/Sun
  for (let h = 9; h < 17; h++) {
    const slotStart = day.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
    const slotEnd = slotStart.plus({ minutes: 60 });
    if (slotStart < leadTime) continue;
    if (overlaps(slotStart.toUTC(), slotEnd.toUTC())) continue;
    const dayKey = slotStart.toISODate();
    (byDay[dayKey] ||= []).push({
      start_at: slotStart.toUTC().toISO(),
      label: slotStart.toFormat('h:mm a'),
    });
  }
}

const days = Object.keys(byDay).sort().map((date) => ({
  date,
  label: DateTime.fromISO(date, { zone: tz }).toFormat('EEEE, MMM d'),
  slots: byDay[date],
}));

return [{
  json: {
    timezone: tz,
    days,
  },
}];

const body = $('Webhook: book-inspection-generic').first().json.body || {};

// Honeypot - a real visitor never fills this (hidden via CSS on the
// public form); a bot filling every field will. Silently pretend
// success without touching the database.
if ((body.website_hp || '').toString().trim()) {
  return [{ json: { spam: true } }];
}

const firstName = (body.first_name || '').toString().trim();
const lastName = (body.last_name || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const phone = (body.phone || '').toString().trim();
const startAt = (body.start_at || '').toString().trim();

if (!firstName) throw new Error('"first_name" is required.');
if (!email || !email.includes('@')) throw new Error('A valid "email" is required.');
if (!startAt) throw new Error('"start_at" is required.');

return [{
  json: {
    spam: false,
    first_name: firstName, last_name: lastName, email, secondary_email: '', phone, secondary_phone: '',
    job_title: '', account_id: null, linkedin_url: '', city: '', state: '', zip_code: '', country: '',
    lead_status: 'New', lead_source: 'Website Booking', timezone: '', birthdate: null,
    do_not_contact: false, dnc_email: false, dnc_call: false, dnc_sms: false,
    createdBy: null, startAt,
  },
}];

const payload = $('Parse Generic Booking Payload').item.json;
const existing = $input.first().json;
return [{ json: { ...payload, existingContactId: existing?.id || null } }];

