const c = $('Postgres: Upsert Contact (Generic)').item.json;
const startAt = $('Parse Generic Booking Payload').item.json.startAt;
const dealId = $('Create Inspection Deal (Generic)').item.json.id;
const activityId = $json.id;
const owner = $('Assign Owner (Round Robin): Generic').item.json;
return [{
  json: {
    contact_id: c.id,
    first_name: c.first_name,
    last_name: $('Parse Generic Booking Payload').item.json.last_name,
    email: c.email,
    unsubscribe_token: c.unsubscribe_token,
    owner_id: owner.owner_id,
    timezone: owner.timezone,
    startAt,
    deal_id: dealId,
    activity_id: activityId,
  },
}];

const NOTIFIER_USER_ID = 1;
const ownerId = $('Parse Followup Payload').item.json.owner_id;
const dmKey = [NOTIFIER_USER_ID, ownerId].sort((a, b) => a - b).join('-');
return [{ json: { notifierUserId: NOTIFIER_USER_ID, ownerId, dmKey } }];

const row = $('Parse Followup Payload').item.json;
const startIso = $('Parse Followup Payload').item.json.startAt;
const tz = row.timezone || 'America/New_York';
const display = DateTime.fromISO(startIso, { zone: 'utc' }).setZone(tz).toFormat("EEEE, MMM d 'at' h:mm a");
const name = [row.first_name, row.last_name].filter(Boolean).join(' ') || 'A lead';
return [{ json: { text: '📅 ' + name + ' just booked their inspection for ' + display + '.' } }];
